#include "common.h"
#include "commit.h"
#include "revwalk.h"

static const int default_table_size = 32;

git_revpool *gitrp_alloc(git_odb *db)
{
	git_revpool *walk = git__malloc(sizeof(*walk));
	if (!walk)
		return NULL;

    memset(walk, 0x0, sizeof(git_revpool));

    walk->commits = git_revpool_table_create(default_table_size);

	walk->db = db;
	return walk;
}

void gitrp_free(git_revpool *walk)
{
    git_commit_list_clear(&(walk->iterator), 0);
    git_commit_list_clear(&(walk->roots), 0);

    git_revpool_table_free(walk->commits);

	free(walk);
}

void gitrp_push(git_revpool *pool, git_commit *commit)
{
    if (commit->object.pool != pool)
        return;

    if (commit->seen)
        return;

    if (!commit->parsed)
    {
        if (git_commit_parse_existing(commit) < 0)
            return;
    }

    // Sanity check: make sure that if the commit
    // has been manually marked as uninteresting,
    // all the parent commits are too.
    if (commit->uninteresting)
        git_commit__mark_uninteresting(commit);

    commit->seen = 1;

    git_commit_list_append(&pool->roots, commit);
}

void gitrp_hide(git_revpool *pool, git_commit *commit)
{
    git_commit__mark_uninteresting(commit);
    gitrp_push(pool, commit);
}

void gitrp_prepare_walk(git_revpool *pool)
{
    git_commit_node *it;

    for (it = pool->roots.head; it != NULL; it = it->next)
    {
        git_commit_list_append(&pool->iterator, it->commit);
    }

    for (it = pool->iterator.head; it != NULL; it = it->next)
    {
        git_commit *commit;
        git_commit_node *parents;

        commit = it->commit;
        parents = commit->parents.head;

        while (parents)
        {
            git_commit *parent = parents->commit;
            parents = parents->next;

            if (parent->seen)
                continue;

            if (parent->parsed == 0)
                git_commit_parse_existing(parent);

            parent->seen = 1;
            git_commit_list_append(&pool->iterator, parent);
        }
    }

    // TODO: topo sort, time sort

    if (pool->sorting & GIT_REVPOOL_SORT_REVERSE)
        pool->next_commit = &git_commit_list_pop_back;
    else
        pool->next_commit = &git_commit_list_pop_front;

    pool->walking = 1;
}

git_commit *gitrp_next(git_revpool *pool)
{
    git_commit *next;

    if (!pool->walking)
        gitrp_prepare_walk(pool);

    while ((next = pool->next_commit(&pool->iterator)) != NULL)
    {
        if (!next->uninteresting)
            return next;
    }

    // No commits left to iterate
    gitrp_reset(pool);
    return NULL;
}

void gitrp_reset(git_revpool *pool)
{
    git_commit_list_clear(&pool->iterator, 0);
    pool->walking = 0;
}

#include "dir.h"

static int init_filter(char *filter, size_t n, const char *dir)
{
	size_t len = strlen(dir);

	if (len+3 >= n)
		return 0;

	strcpy(filter, dir);
	if (len && dir[len-1] != '/')
		strcat(filter, "/");
	strcat(filter, "*");

	return 1;
}

DIR *opendir(const char *dir)
{
	char filter[4096];
	DIR *new;

	if (!dir || !init_filter(filter, sizeof(filter), dir))
		return NULL;

	new = git__malloc(sizeof(*new));
	if (!new)
		return NULL;

	new->dir = git__malloc(strlen(dir)+1);
	if (!new->dir) {
		free(new);
		return NULL;
	}
	strcpy(new->dir, dir);

	new->h = FindFirstFile(filter, &new->f);
	if (new->h == INVALID_HANDLE_VALUE) {
		free(new->dir);
		free(new);
		return NULL;
	}
	new->first = 1;

	return new;
}

struct dirent *readdir(DIR *d)
{
	if (!d || d->h == INVALID_HANDLE_VALUE)
		return NULL;

	if (d->first)
		d->first = 0;
	else {
		if (!FindNextFile(d->h, &d->f))
			return NULL;
	}

	if (strlen(d->f.cFileName) >= sizeof(d->entry.d_name))
		return NULL;

	d->entry.d_ino = 0;
	strcpy(d->entry.d_name, d->f.cFileName);

	return &d->entry;
}

void rewinddir(DIR *d)
{
	char filter[4096];

	if (d) {
		if (d->h != INVALID_HANDLE_VALUE)
			FindClose(d->h);
		d->h = INVALID_HANDLE_VALUE;
		d->first = 0;
		if (init_filter(filter, sizeof(filter), d->dir)) {
			d->h = FindFirstFile(filter, &d->f);
			if (d->h != INVALID_HANDLE_VALUE)
				d->first = 1;
		}
	}
}

int closedir(DIR *d)
{
	if (d) {
		if (d->h != INVALID_HANDLE_VALUE)
			FindClose(d->h);
		if (d->dir)
			free(d->dir);
		free(d);
	}
	return 0;
}

