int *git__errno_storage(void)
{
	int *e = pthread_getspecific(errno_key);
	if (!e) {
#undef calloc
		e = calloc(1, sizeof(*e));
#define calloc(a,b) GIT__FORBID_MALLOC
		pthread_setspecific(errno_key, e);
	}
	return e;
}

