git_tree *git_tree_parse(git_revpool *pool, const git_oid *id)
{
	git_tree *tree = NULL;

	if ((tree = git_tree_lookup(pool, id)) == NULL)
		return NULL;

	if (git_tree__parse(tree) < 0)
		goto error_cleanup;

	return tree;

error_cleanup:
	/* FIXME: do not free; the tree is owned by the revpool */
	free(tree);
	return NULL;
}

int git_tree__parse(git_tree *tree)
{
	static const char tree_header[] = {'t', 'r', 'e', 'e', ' '};

	int error = 0;
	git_obj odb_object;
	char *buffer, *buffer_end;

	error = git_odb_read(&odb_object, tree->object.pool->db, &tree->object.id);
	if (error < 0)
		return error;

	buffer = odb_object.data;
	buffer_end = odb_object.data + odb_object.len;

	if (memcmp(buffer, tree_header, 5) != 0)
		return GIT_EOBJCORRUPTED;

	buffer += 5;

	tree->byte_size = strtol(buffer, &buffer, 10);

	if (*buffer++ != 0)
		return GIT_EOBJCORRUPTED;

	while (buffer < buffer_end) {
		git_tree_entry *entry;

		entry = git__malloc(sizeof(git_tree_entry));
		entry->next = tree->entries;

		entry->attr = strtol(buffer, &buffer, 10);

		if (*buffer++ != ' ') {
			error = GIT_EOBJCORRUPTED;
			break;
		}

		entry->filename = git__strdup(buffer);

		if (entry->filename == NULL) {
			error = GIT_EOBJCORRUPTED;
			break;
		}
		buffer += strlen(entry->filename);

		git_oid_mkraw(&entry->oid, (const unsigned char *)buffer);
		buffer += GIT_OID_RAWSZ;

		tree->entries = entry;
	}

	return error;
}

#include "map.h"
#include <sys/mman.h>
#include <errno.h>


int git__mmap(git_map *out, size_t len, int prot, int flags, int fd, off_t offset)
{
	int mprot = 0;
	int mflag = 0;

	assert((out != NULL) && (len > 0));

	if ((out == NULL) || (len == 0)) {
		errno = EINVAL;
		return GIT_ERROR;
	}

	out->data = NULL;
	out->len = 0;

	if (prot & GIT_PROT_WRITE)
		mprot = PROT_WRITE;
	else if (prot & GIT_PROT_READ)
		mprot = PROT_READ;
	else {
		errno = EINVAL;
		return GIT_ERROR;
	}

	if ((flags & GIT_MAP_TYPE) == GIT_MAP_SHARED)
		mflag = MAP_SHARED;
	else if ((flags & GIT_MAP_TYPE) == GIT_MAP_PRIVATE)
		mflag = MAP_PRIVATE;

	if (flags & GIT_MAP_FIXED) {
		errno = EINVAL;
		return GIT_ERROR;
	}

	out->data = mmap(NULL, len, mprot, mflag, fd, offset);
	if (!out->data || out->data == MAP_FAILED)
		return git_os_error();
	out->len = len;

	return GIT_SUCCESS;
}

int git__munmap(git_map *map)
{
	assert(map != NULL);

	if (!map)
		return GIT_ERROR;

	munmap(map->data, map->len);

	return GIT_SUCCESS;
}

