static const char INDEX_HEADER_SIG[] = {'D', 'I', 'R', 'C'};
static const char INDEX_EXT_TREECACHE_SIG[] = {'T', 'R', 'E', 'E'};

static const size_t INDEX_ENTRY_SIZE = 62;
static const size_t INDEX_FOOTER_SIZE = GIT_OID_RAWSZ;
static const size_t INDEX_HEADER_SIZE = 12;

static const unsigned int INDEX_VERSION_NUMBER = 2;

git_index *git_index_alloc(const char *index_path)
{
	git_index *index;

	if (index_path == NULL)
		return NULL;

	index = git__malloc(sizeof(git_index));
	if (index == NULL)
		return NULL;

	memset(index, 0x0, sizeof(git_index));

	index->index_file_path = git__strdup(index_path);
	if (index->index_file_path == NULL) {
		free(index);
		return NULL;
	}

	/* Check if index file is stored on disk already */
	if (gitfo_exists(index->index_file_path) == 0)
		index->on_disk = 1;

	return index;
}

void git_index_clear(git_index *index)
{
	unsigned int i;
	for (i = 0; i < index->entry_count; ++i)
		free(index->entries[i].path);

	index->entry_count = 0;
	index->last_modified = 0;
	index->sorted = 1;
}

void git_index_free(git_index *index)
{
	free(index->entries);
	index->entries = NULL;
	free(index->index_file_path);
	free(index);
}


int git_index_read(git_index *index)
{
	struct stat indexst;
	int error = 0;

	if (index->index_file_path == NULL)
		return GIT_ERROR;

	if (!index->on_disk || gitfo_exists(index->index_file_path) < 0) {
		git_index_clear(index);
		index->on_disk = 0;
		return 0;
	}

	if (gitfo_stat(index->index_file_path, &indexst) < 0)
		return GIT_EOSERR;

	if (indexst.st_mtime != index->last_modified) {

		gitfo_buf buffer;

		if (gitfo_read_file(&buffer, index->index_file_path) < 0)
			return GIT_EOSERR;

		git_index_clear(index);
		error = git_index__parse(index, buffer.data, buffer.len);

		if (error == 0)
			index->last_modified = indexst.st_mtime;

		gitfo_free_buf(&buffer);
	}

	return error;
}

int git_index_write(git_index *index)
{
	git_filelock file;
	struct stat indexst;

	if (!index->sorted)
		git_index__sort(index);

	if (git_filelock_init(&file, index->index_file_path) < 0)
		return GIT_EOSERR;

	if (git_filelock_lock(&file, 0) < 0)
		return GIT_EOSERR;

	if (git_index__write(index, &file) < 0) {
		git_filelock_unlock(&file);
		return GIT_EOSERR;
	}

	if (git_filelock_commit(&file) < 0)
		return GIT_EOSERR;

	if (gitfo_stat(index->index_file_path, &indexst) == 0) {
		index->last_modified = indexst.st_mtime;
		index->on_disk = 1;
	}

	return 0;
}

void git_index__sort(git_index *index)
{
	git_index_entry pivot;
	int i, j;

	if (index->sorted)
		return;

	for (i = 1; i < (int)index->entry_count; ++i) {

		memcpy(&pivot, &index->entries[i], sizeof(git_index_entry));
		j = i - 1;

		while (j >= 0 && strcmp(pivot.path, index->entries[j].path) < 0) {
			memcpy(&index->entries[j + 1], &index->entries[j], sizeof(git_index_entry));
			j = j - 1;
		}

		memcpy(&index->entries[j + 1], &pivot, sizeof(git_index_entry));
	}

	index->sorted = 1;
}

int git_index__append(git_index *index, const git_index_entry *source_entry)
{
	git_index_entry *offset;

	/* Resize the entries array */
	if (index->entry_count + 1 > index->entries_size) {
		git_index_entry *new_entries;
		size_t new_size;

		new_size = (unsigned int)(index->entries_size * 1.5f);
		if ((new_entries = git__malloc(new_size * sizeof(git_index_entry))) == NULL)
			return GIT_ENOMEM;

		memcpy(new_entries, index->entries, index->entry_count * sizeof(git_index_entry));
		free(index->entries);

		index->entries_size = new_size;
		index->entries = new_entries;
	}

	offset = &index->entries[index->entry_count];
	index->entry_count++;

	memcpy(offset, source_entry, sizeof(git_index_entry));
	index->sorted = 0;

	return 0;
}

int git_index__remove_pos(git_index *index, unsigned int position)
{
	git_index_entry *offset;
	size_t copy_size;

	offset = &index->entries[position];
	index->entry_count--;
	copy_size = (index->entry_count - position) * sizeof(git_index_entry);

	memcpy(offset, offset + sizeof(git_index_entry), copy_size);

	return 0;
}

int git_index_find(git_index *index, const char *path)
{
	int low = 0, high = index->entry_count;

	if (!index->sorted)
		git_index__sort(index);

	while (low < high) {
		int mid = (low + high) >> 1;
		int cmp = strcmp(path, index->entries[mid].path);

		if (cmp < 0)
			high = mid;

		else if (cmp == 0) {

			while (mid > 0 && strcmp(path, index->entries[mid - 1].path) == 0)
				mid--;

			return mid;

		} else
			low = mid + 1;
	}

	return GIT_ENOTFOUND; /* NOT FOUND */
}

int git_index__parse_treecache(git_index *index, const char *buffer, size_t buffer_size)
{
	/* TODO: parse tree caches */

	/*
	 * A number of entries:
	 *
	 *	NUL-terminated tree name
	 *
	 *	Blank-terminated ASCII decimal number of entries in this tree
	 *
	 *	Newline-terminated position of this tree in the parent tree. 0 for
	 *	the root tree
	 *
	 *	160-bit SHA-1 for this tree and it's children
	 */

	return 0;
}

int git_index__parse(git_index *index, const char *buffer, size_t buffer_size)
{
	unsigned int version_number, i;
	git_oid checksum_calculated, checksum_expected;

	/*
	 * Header:
	 * A twelve byte header consisting of
	 *
	 *	4 byte signature:
	 *		The signature is { 'D', 'I', 'R', 'C' }
	 *
	 *	4 byte version number:
	 *		The current version is 2
	 *
	 *	32-bit number of index entries.
	 */

	if (buffer_size < INDEX_HEADER_SIZE + INDEX_FOOTER_SIZE)
		return GIT_EOBJCORRUPTED;


	/* Precalculate the SHA1 of the files's contents -- we'll match it to
	 * the provided SHA1 in the footer */
	git_hash_buf(&checksum_calculated, (const void *)buffer, buffer_size - INDEX_FOOTER_SIZE);


	/* check header signature */
	if (memcmp(buffer, INDEX_HEADER_SIG, 4) != 0)
		return GIT_EOBJCORRUPTED;
	buffer += 4;

	/* check version number */
	version_number = ntohl(*(unsigned int *)buffer);
	if (version_number != INDEX_VERSION_NUMBER)
		return GIT_EOBJCORRUPTED;
	buffer += 4;


	/* get entry count */
	index->entry_count = ntohl(*(unsigned int *)buffer);
	buffer += 4;

	buffer_size -= INDEX_HEADER_SIZE;

	if (index->entry_count > index->entries_size) {
		free(index->entries);
		index->entries_size = (unsigned int)(index->entry_count * 1.3f);
		index->entries = git__malloc(index->entries_size * sizeof(git_index_entry));
	}

	for (i = 0; i < index->entry_count && buffer_size > INDEX_FOOTER_SIZE; ++i) {

		git_index_entry *entry;
		unsigned int *word_buffer;

		buffer_size -= INDEX_ENTRY_SIZE;
		if (buffer_size <= INDEX_FOOTER_SIZE)
			return GIT_EOBJCORRUPTED;

		entry = &index->entries[i];
		word_buffer = (unsigned int *)buffer;
		buffer += INDEX_ENTRY_SIZE;

		/* 32-bit ctime seconds, the last time a file's metadata changed */
		entry->ctime_s  = ntohl(*word_buffer++);

		/* 32-bit ctime nanoseconds (modulo 1G) */
		entry->ctime_ns = ntohl(*word_buffer++);

		/* 32-bit mtime seconds, the last time a file's data changed */
		entry->mtime_s  = ntohl(*word_buffer++);

		/* 32-bit mtime nanoseconds (modulo 1G) */
		entry->mtime_ns = ntohl(*word_buffer++);

		/* 32-bit dev */
		entry->dev = ntohl(*word_buffer++);

		/* 32-bit i-node number */
		entry->ino = ntohl(*word_buffer++);

		/* 32-bit mode flags */
		entry->mode = ntohl(*word_buffer++);

		/* 32-bit uid */
		entry->uid = ntohl(*word_buffer++);

		/*     32-bit gid */
		entry->gid = ntohl(*word_buffer++);

		/*     32-bit file size */
		entry->file_size = ntohl(*word_buffer++);

		/* 160-bit SHA-1 for the represented blob */
		git_oid_mkraw(&entry->oid, (const unsigned char *)word_buffer);

		/*
		 * A 16-bit field split into (high to low bits)
		 *
		 *		1-bit assume-valid flag
		 *		1-bit update-needed flag
		 *		2-bit stage (during merge)
		 *		12-bit name length
		 */
		entry->flags.raw = ntohs(*(unsigned short *)(buffer - 2));

		if (entry->flags.path_length == 0 || entry->flags.path_length > GIT_PATH_MAX - 1)
			return GIT_EOBJCORRUPTED;

		buffer_size -= entry->flags.path_length;
		if (buffer_size <= INDEX_FOOTER_SIZE)
			return GIT_EOBJCORRUPTED;

		entry->path = git__strdup(buffer);

		if (strlen(entry->path) != entry->flags.path_length)
			return GIT_EOBJCORRUPTED;

		buffer += entry->flags.path_length;

		while (buffer_size > INDEX_FOOTER_SIZE && *buffer == 0)
			buffer_size--, buffer++;
	}

	/* There's still space for some extensions! */
	while (buffer_size > INDEX_FOOTER_SIZE) {

		char ext_signature[4];
		int ext_size;

		/*
		 * 4 byte extension signature. If the first byte is 'A'..'Z' the
		 *	extension is optional and can be ignored.
		 *
		 *	32-bit size of the extension
		 *
		 *	Extension data
		 */

		memcpy(ext_signature, buffer, 4);
		buffer += 4;

		ext_size = ntohl(*(unsigned int *)buffer);
		buffer += 4;

		buffer_size -= (8 + ext_size);

		if (buffer_size < INDEX_FOOTER_SIZE)
			return GIT_EOBJCORRUPTED;

		/* optional extension */
		if (ext_signature[0] >= 'A' && ext_signature[0] <= 'Z') {

			/* tree cache */
			if (memcmp(ext_signature, INDEX_EXT_TREECACHE_SIG, 4) == 0) {

				if (git_index__parse_treecache(index, buffer, ext_size) < 0)
					return GIT_ERROR;
			}

		} else {

			/* we cannot handle non-ignorable extensions;
			 * in fact they aren't even defined in the standard */
			return GIT_ERROR;
		}

		buffer += ext_size;
	}

	if (buffer_size != INDEX_FOOTER_SIZE)
		return GIT_EOBJCORRUPTED;

	/* 160-bit SHA-1 over the content of the index file before this checksum. */
	git_oid_mkraw(&checksum_expected, (const unsigned char *)buffer);

	if (git_oid_cmp(&checksum_calculated, &checksum_expected) != 0)
		return GIT_EOBJCORRUPTED;

	return 0;
}

int git_index__write(git_index *index, git_filelock *file)
{
	static const char NULL_BYTES[] = {0, 0, 0, 0, 0, 0, 0, 0};

	int error = 0;
	unsigned int i;

	git_hash_ctx *digest;
	git_oid hash_final;

	if (index == NULL || file == NULL || !file->is_locked)
		return GIT_ERROR;

	if ((digest = git_hash_new_ctx()) == NULL)
		return GIT_ERROR;

#define WRITE_WORD(_word) {\
	unsigned int network_word = htonl((_word));\
	git_filelock_write(file, &network_word, 4);\
	git_hash_update(digest, &network_word, 4);\
}

#define WRITE_SHORT(_shrt) {\
	unsigned short network_shrt = htons((_shrt));\
	git_filelock_write(file, &network_shrt, 2);\
	git_hash_update(digest, &network_shrt, 2);\
}

#define WRITE_BYTES(_bytes, _n) {\
	git_filelock_write(file, _bytes, _n);\
	git_hash_update(digest, _bytes, _n);\
}

	WRITE_BYTES(INDEX_HEADER_SIG, 4);

	WRITE_WORD(INDEX_VERSION_NUMBER);
	WRITE_WORD(index->entry_count);

	for (i = 0; i < index->entry_count; ++i) {
		git_index_entry *entry;
		int padding;

		entry = &index->entries[i];

		WRITE_WORD(entry->ctime_s);
		WRITE_WORD(entry->ctime_ns);
		WRITE_WORD(entry->mtime_s);
		WRITE_WORD(entry->mtime_ns);
		WRITE_WORD(entry->dev);
		WRITE_WORD(entry->ino);
		WRITE_WORD(entry->mode);
		WRITE_WORD(entry->uid);
		WRITE_WORD(entry->gid);
		WRITE_WORD(entry->file_size);
		WRITE_BYTES(entry->oid.id, GIT_OID_RAWSZ);
		WRITE_SHORT(entry->flags.raw);

		padding = 8 - ((INDEX_ENTRY_SIZE + entry->flags.path_length) & 0x7);
		WRITE_BYTES(entry->path, entry->flags.path_length);
		WRITE_BYTES(NULL_BYTES, padding);
	}

#undef WRITE_WORD
#undef WRITE_BYTES
#undef WRITE_SHORT

	/* TODO: write extensions (tree cache) */

	git_hash_final(&hash_final, digest);
	git_filelock_write(file, hash_final.id, GIT_OID_RAWSZ);

	return error;
}

#include "fileops.h"

int gitfo_read(git_file fd, void *buf, size_t cnt)
{
	char *b = buf;
	while (cnt) {
		ssize_t r = read(fd, b, cnt);
		if (r < 0) {
			if (errno == EINTR || errno == EAGAIN)
				continue;
			return -1;
		}
		if (!r) {
			errno = EPIPE;
			return -1;
		}
		cnt -= r;
		b += r;
	}
	return GIT_SUCCESS;
}

int gitfo_write(git_file fd, void *buf, size_t cnt)
{
	char *b = buf;
	while (cnt) {
		ssize_t r = write(fd, b, cnt);
		if (r < 0) {
			if (errno == EINTR || errno == EAGAIN)
				continue;
			return -1;
		}
		if (!r) {
			errno = EPIPE;
			return -1;
		}
		cnt -= r;
		b += r;
	}
	return GIT_SUCCESS;
}

off_t gitfo_size(git_file fd)
{
	gitfo_statbuf sb;
	if (fstat(fd, &sb))
		return -1;
	return sb.st_size;
}

/* cached diskio */
struct gitfo_cache {
	git_file fd;
	unsigned int cache_size, pos;
	void *cache;
};

gitfo_cache *gitfo_enable_caching(git_file fd, size_t cache_size)
{
	gitfo_cache *ioc;

	ioc = malloc(sizeof(*ioc));
	if (!ioc)
		return NULL;

	ioc->pos = 0;
	ioc->cache_size = cache_size;
	ioc->cache = malloc(cache_size);
	if (!ioc->cache) {
		free(ioc);
		return NULL;
	}

	return ioc;
}

static inline void gitfo_add_to_cache(gitfo_cache *ioc, void *buf, size_t len)
{
	memcpy(ioc->cache + ioc->pos, buf, len);
	ioc->pos += len;
}

int gitfo_flush_cached(gitfo_cache *ioc)
{
	int result = GIT_SUCCESS;

	if (ioc->pos) {
		result = gitfo_write(ioc->fd, ioc->cache, ioc->pos);
		ioc->pos = 0;
	}

	return result;
}

int gitfo_write_cached(gitfo_cache *ioc, void *buf, size_t len)
{
	for (;;) {
		size_t space_left = ioc->cache_size - ioc->pos;
		/* cache if it's small */
		if (space_left > len) {
			gitfo_add_to_cache(ioc, buf, len);
			return GIT_SUCCESS;
		}

		/* flush the cache if it doesn't fit */
		if (ioc->pos) {
			int rc;
			gitfo_add_to_cache(ioc, buf, space_left);
			rc = gitfo_flush_cached(ioc);
			if (rc < 0)
				return rc;

			len -= space_left;
			buf += space_left;
		}

		/* write too-large chunks immediately */
		if (len > ioc->cache_size)
			return gitfo_write(ioc->fd, buf, len);
	}
	return GIT_SUCCESS;
}

int gitfo_close_cached(gitfo_cache *ioc)
{
	git_file fd;

	if (gitfo_flush_cached(ioc) < 0)
		return -1;

	fd = ioc->fd;
	free(ioc->cache);
	free(ioc);

	return gitfo_close(fd);
}

