const git_oid *git_commit_id(git_commit *c)
{
	return &c->id;
}

git_commit *git_commit_lookup(git_revpool *pool, const git_oid *id)
{
    git_obj commit_obj;
    git_commit *commit = NULL;

    /*
     * TODO: check if the commit is already cached in the
     * revpool instead of loading it from the odb
     */

    if (git_odb_read(&commit_obj, pool->db, id) < 0)
        return NULL;

    if (commit_obj.type != GIT_OBJ_COMMIT)
        goto error_cleanup;

    commit = git__malloc(sizeof(git_commit));
    memset(commit, 0x0, sizeof(git_commit));

    git_oid_cpy(&commit->id, id);
    commit->pool = pool;

    if (git_commit__parse_buffer(commit, commit_obj.data, commit_obj.len) < 0)
        goto error_cleanup;

    return commit;

error_cleanup:
    git_obj_close(&commit_obj);
    free(commit);

    return NULL;
}

int git_commit__parse_time(time_t *commit_time, char *buffer, const char *buffer_end)
{
	if (memcmp(buffer, "author ", 7) != 0)
		return -1;

    buffer = memchr(buffer, '\n', buffer_end - buffer);
    if (buffer == 0 || buffer >= buffer_end)
        return -1;

	if (memcmp(buffer, "committer ", 10) != 0)
		return -1;

    buffer = memchr(buffer, '\n', buffer_end - buffer);
    if (buffer == 0 || buffer >= buffer_end)
        return -1;

	*commit_time = strtol(buffer, &buffer, 10);

    return (buffer < buffer_end) ? 0 : -1;
}

int git_commit__parse_oid(git_oid *oid, char **buffer_out, const char *buffer_end, const char *header)
{
    size_t sha_len = GIT_OID_HEXSZ;
    size_t header_len = strlen(header);

    char *buffer = *buffer_out;

    if (buffer + (header_len + sha_len + 1) > buffer_end)
        return -1;

    if (memcmp(buffer, header, header_len) != 0)
        return -1;

    if (buffer[header_len + sha_len] != '\n')
        return -1;

    if (git_oid_mkstr(oid, buffer + header_len) < 0)
        return -1;

    *buffer_out = buffer + (header_len + sha_len + 1);

    return 0;
}

int git_commit__parse_buffer(git_commit *commit, void *data, size_t len)
{
	char *buffer = (char *)data;
	const char *buffer_end = (char *)data + len;

    git_oid oid;

    if (commit->parsed)
		return 0;

    if (git_commit__parse_oid(&oid, &buffer, buffer_end, "tree ") < 0)
        return -1;

    /*
     * TODO: load tree into commit object
     * TODO: commit grafts!
     */

    while (git_commit__parse_oid(&oid, &buffer, buffer_end, "parent ") == 0) {
        git_commit *parent;

        if ((parent = git_commit_lookup(commit->pool, &oid)) == NULL)
            return -1;

        // TODO: push the new commit into the revpool
    }

    if (git_commit__parse_time(&commit->commit_time, buffer, buffer_end) < 0)
        return -1;

    commit->parsed = 1;

	return 0;
}

#include "test_lib.h"
#include "fileops.h"


typedef struct name_data {
	int  count;  /* return count */
	char *name;  /* filename     */
} name_data;

typedef struct walk_data {
	char *sub;        /* sub-directory name */
	name_data *names; /* name state data    */
} walk_data;


static char path_buffer[GIT_PATH_MAX];
static char *top_dir = "dir-walk";
static walk_data *state_loc;


static int error(const char *fmt, ...)
{
	va_list ap;

	va_start(ap, fmt);
	vfprintf(stderr, fmt, ap);
	va_end(ap);
	fprintf(stderr, "\n");
	return -1;
}

static int setup(walk_data *d)
{
	name_data *n;

	if (gitfo_mkdir(top_dir, 0755) < 0)
		return error("can't mkdir(\"%s\")", top_dir);

	if (gitfo_chdir(top_dir) < 0)
		return error("can't chdir(\"%s\")", top_dir);

	if (strcmp(d->sub, ".") != 0)
		if (gitfo_mkdir(d->sub, 0755) < 0)
			return error("can't mkdir(\"%s\")", d->sub);

	strcpy(path_buffer, d->sub);
	state_loc = d;

	for (n = d->names; n->name; n++) {
		git_file fd = gitfo_creat(n->name, 0600);
		must_be_true(fd >= 0);
		gitfo_close(fd);
		n->count = 0;
	}

	return 0;
}

static int knockdown(walk_data *d)
{
	name_data *n;

	for (n = d->names; n->name; n++) {
		if (gitfo_unlink(n->name) < 0)
			return error("can't unlink(\"%s\")", n->name);
	}

	if (strcmp(d->sub, ".") != 0)
		if (gitfo_rmdir(d->sub) < 0)
			return error("can't rmdir(\"%s\")", d->sub);

	if (gitfo_chdir("..") < 0)
		return error("can't chdir(\"..\")");

	if (gitfo_rmdir(top_dir) < 0)
		return error("can't rmdir(\"%s\")", top_dir);

	return 0;
}

static int check_counts(walk_data *d)
{
	int ret = 0;
	name_data *n;

	for (n = d->names; n->name; n++) {
		if (n->count != 1)
			ret = error("count (%d, %s)", n->count, n->name);
	}
	return ret;
}

static int one_entry(void *state, char *path)
{
	walk_data *d = (walk_data *) state;
	name_data *n;

	must_be_true(state == state_loc);
	must_be_true(path == path_buffer);
	for (n = d->names; n->name; n++) {
		if (!strcmp(n->name, path)) {
			n->count++;
			return 0;
		}
	}
	test_die("unexpected path \"%s\"", path);
}


static name_data dot_names[] = {
	{ 0, "./a" },
	{ 0, "./asdf" },
	{ 0, "./pack-foo.pack" },
	{ 0, NULL }
};
static walk_data dot = {
