BEGIN_TEST(query_details_test)
	const size_t commit_count = sizeof(commit_ids) / sizeof(const char *);

	unsigned int i;
	git_odb *db;
	git_revpool *pool;

	must_pass(git_odb_open(&db, odb_dir));

	pool = gitrp_alloc(db);
	must_be_true(pool != NULL);

	for (i = 0; i < commit_count; ++i) {
		git_oid id;
