static const char *GIT_FILELOCK_EXTENSION = ".lock";

int git_filelock_init(git_filelock *lock, const char *path)
{
	const size_t ext_length = strlen(GIT_FILELOCK_EXTENSION);
	size_t path_length;

	if (lock == NULL || path == NULL)
		return GIT_ERROR;

	if (!gitfo_exists(path))
		return GIT_EOSERR;

	path_length = strlen(path);

	if (path_length + ext_length >= GIT_PATH_MAX)
		return GIT_ERROR;

	memset(lock, 0x0, sizeof(git_filelock));

	memcpy(lock->path_original, path, path_length);
	memcpy(lock->path_lock, path, path_length);
	memcpy(lock->path_lock + path_length, GIT_FILELOCK_EXTENSION, ext_length);

	return 0;
}

int git_filelock_lock(git_filelock *lock, int append)
{
	if (gitfo_exists(lock->path_lock))
		return GIT_EOSERR;

	lock->file_lock = gitfo_creat(lock->path_lock, O_EXCL);

	if (lock->file_lock < 0)
		return GIT_EOSERR;

	lock->is_locked = 1;

	/* TODO: do a flock() in the descriptor file_lock */

	if (append && gitfo_exists(lock->path_original)) {
		git_file source;
		char buffer[2048];
		size_t read_bytes;

		source = gitfo_open(lock->path_original, O_RDONLY);
		if (source < 0)
			return GIT_EOSERR;

		while ((read_bytes = gitfo_read(source, buffer, 2048)) > 0)
			gitfo_write(lock->file_lock, buffer, read_bytes);

		gitfo_close(source);
	}

	return 0;
}

void git_filelock_unlock(git_filelock *lock)
{
	if (lock->is_locked) {
		/* The flock() in lock->file_lock is removed
		 * automatically when closing the descriptor */
		gitfo_close(lock->file_lock);
		gitfo_unlink(lock->path_lock);
		lock->is_locked = 0;
	}
}

int git_filelock_commit(git_filelock *lock)
{
	int error;

	if (!lock->is_locked || lock->file_lock < 0)
		return GIT_ERROR;

	/* FIXME: flush the descriptor? */
	gitfo_close(lock->file_lock);

	error = gitfo_move_file(lock->path_lock, lock->path_original);

	if (error < 0)
		gitfo_unlink(lock->path_lock);

	lock->is_locked = 0;
	return error;
}

int git_filelock_write(git_filelock *lock, const void *buffer, size_t length)
{
	if (!lock->is_locked || lock->file_lock < 0)
		return GIT_ERROR;

	return gitfo_write(lock->file_lock, (void *)buffer, length);
}

